import { useState } from 'react';
import {
    Box,
    TextField,
    Button,
} from '@mui/material';
import axios from 'axios';

const endpointMapping = {
    'Notion': 'notion',
    'Airtable': 'airtable',
    'HubSpot': 'hubspot',
};

export const DataForm = ({ integrationType, credentials }) => {
    const [loadedData, setLoadedData] = useState(null);
    const [insights, setInsights] = useState(null);
    const endpoint = endpointMapping[integrationType];

    const handleLoad = async () => {
        try {
            const formData = new FormData();
            formData.append('credentials', JSON.stringify(credentials));
            const response = await axios.post(`http://localhost:8000/integrations/${endpoint}/load`, formData);
            const data = response.data;
            setLoadedData(JSON.stringify(data, null, 2));
            setInsights(null);
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    }

    const handleInsights = async () => {
        try {
            if (!loadedData) {
                alert('Load integration data before generating insights.');
                return;
            }
            const formData = new FormData();
            formData.append('integration_type', integrationType);
            formData.append('items', loadedData);
            const response = await axios.post('http://localhost:8000/integrations/insights', formData);
            setInsights(JSON.stringify(response.data, null, 2));
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    return (
        <Box display='flex' justifyContent='center' alignItems='center' flexDirection='column' width='100%'>
            <Box display='flex' flexDirection='column' width='100%'>
                <TextField
                    label="Loaded Data"
                    value={loadedData || ''}
                    sx={{mt: 2}}
                    InputLabelProps={{ shrink: true }}
                    disabled
                />
                <Button
                    onClick={handleLoad}
                    sx={{mt: 2}}
                    variant='contained'
                >
                    Load Data
                </Button>
                <Button
                    onClick={handleInsights}
                    sx={{mt: 1}}
                    variant='contained'
                >
                    Generate Insights
                </Button>
                <Button
                    onClick={() => {
                        setLoadedData(null);
                        setInsights(null);
                    }}
                    sx={{mt: 1}}
                    variant='contained'
                >
                    Clear Data
                </Button>
                <TextField
                    label="AI Insights"
                    value={insights || ''}
                    sx={{mt: 2}}
                    InputLabelProps={{ shrink: true }}
                    disabled
                />
            </Box>
        </Box>
    );
}
